CREATE TABLE gathering (id uuid PRIMARY KEY,church_id uuid NOT NULL REFERENCES church(id),name text NOT NULL,organization_id uuid,schedule text NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(church_id,id),FOREIGN KEY(church_id,organization_id) REFERENCES organization(church_id,id));
CREATE TABLE gathering_session (id uuid PRIMARY KEY,church_id uuid NOT NULL,gathering_id uuid NOT NULL,starts_at timestamptz NOT NULL,UNIQUE(church_id,id),UNIQUE(church_id,gathering_id,starts_at),FOREIGN KEY(church_id,gathering_id) REFERENCES gathering(church_id,id));
CREATE TABLE attendance_record (id uuid PRIMARY KEY,church_id uuid NOT NULL,session_id uuid NOT NULL,member_id uuid NOT NULL,status text NOT NULL CHECK(status IN ('PRESENT','ABSENT','LATE','EXCUSED','UNKNOWN')),source text NOT NULL CHECK(source IN ('MANUAL','BULK')),version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(church_id,id),UNIQUE(church_id,session_id,member_id),FOREIGN KEY(church_id,session_id) REFERENCES gathering_session(church_id,id),FOREIGN KEY(church_id,member_id) REFERENCES member(church_id,id),FOREIGN KEY(church_id,updated_by) REFERENCES app_user(church_id,id));
CREATE TABLE attendance_change (id uuid PRIMARY KEY,church_id uuid NOT NULL,record_id uuid NOT NULL,from_status text,to_status text NOT NULL,source text NOT NULL,actor_id uuid NOT NULL,version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(church_id,record_id) REFERENCES attendance_record(church_id,id),FOREIGN KEY(church_id,actor_id) REFERENCES app_user(church_id,id),UNIQUE(record_id,version));
CREATE FUNCTION prevent_operation_history_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Operation history is immutable' USING ERRCODE='23514'; END $$;
CREATE TRIGGER attendance_history_immutable BEFORE UPDATE OR DELETE ON attendance_change FOR EACH ROW EXECUTE FUNCTION prevent_operation_history_change();
INSERT INTO permission(code) VALUES ('attendance.read'),('attendance.write');
INSERT INTO role_permission(role_id,permission_code) SELECT role_id,p.code FROM role_permission r CROSS JOIN (VALUES ('attendance.read'),('attendance.write')) p(code) WHERE r.permission_code='identity.manage';
CREATE INDEX attendance_member_idx ON attendance_record(church_id,member_id);
CREATE INDEX gathering_session_date_idx ON gathering_session(church_id,starts_at);
